// Generates src/lib/providerIconData.ts: a curated, OFFLINE subset of the
// LobeHub AI brand icons (@lobehub/icons-static-svg, MIT). Only the providers
// Prompture can route to are extracted, so the app ships a few dozen KB of SVG
// instead of 900+ icons and never fetches a logo over the network.
//
// Run `npm run gen:icons` after adding a provider to CURATED. The package is a
// devDependency used only here; the generated file is committed.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const iconDir = resolve(root, "node_modules/@lobehub/icons-static-svg/icons");

// Prompture provider id -> LobeHub icon name (the "-color" variant when there is one).
const CURATED = {
  claude: "claude-color",
  anthropic: "claude-color",
  openai: "openai",
  gemini: "gemini-color",
  google: "gemini-color",
  vertex: "vertexai-color",
  deepseek: "deepseek-color",
  mistral: "mistral-color",
  qwen: "qwen-color",
  groq: "groq",
  grok: "grok",
  xai: "grok",
  moonshot: "kimi-color",
  kimi: "kimi-color",
  ollama: "ollama",
  openrouter: "openrouter-color",
  lmstudio: "lmstudio",
  zai: "zhipu-color",
  zhipu: "zhipu-color",
  cohere: "cohere-color",
  perplexity: "perplexity-color",
  huggingface: "huggingface-color",
  hugging: "huggingface-color",
  azure: "azure-color",
  fireworks: "fireworks-color",
  together: "together-color",
  cerebras: "cerebras-color",
  minimax: "minimax-color",
  modelscope: "modelscope-color",
  sambanova: "sambanova-color",
  bedrock: "bedrock-color",
  nvidia: "nvidia-color",
};

// Strip provenance metadata and fixed sizes; keep the drawing.
function clean(svg) {
  return svg
    .replace(/<metadata>[\s\S]*?<\/metadata>/g, "")
    .replace(/\s(width|height)="[^"]*"/g, "")
    .replace(/\sstyle="[^"]*"/, "")
    .replace(/\sxmlns:c2pa="[^"]*"/, "")
    .trim();
}

const icons = {};
for (const name of new Set(Object.values(CURATED))) {
  icons[name] = clean(readFileSync(resolve(iconDir, `${name}.svg`), "utf8"));
}

const out = `// AUTO-GENERATED by scripts/gen-provider-icons.mjs from @lobehub/icons-static-svg (MIT).
// Do not edit by hand: change CURATED in the script and run \`npm run gen:icons\`.

export const PROVIDER_ICON: Record<string, string> = ${JSON.stringify(CURATED, null, 2)};

export const ICON_SVG: Record<string, string> = ${JSON.stringify(icons, null, 2)};
`;
writeFileSync(resolve(root, "src/lib/providerIconData.ts"), out);
console.log(`providerIconData.ts: ${Object.keys(icons).length} icons for ${Object.keys(CURATED).length} providers`);
